#!/bin/sh
# Restore one target copy; baseline is embedded, no repository dependency.
set -eu
if [ "$#" -ne 1 ]; then printf 'usage: %s TARGET_COPY\n' "$0" >&2; exit 2; fi
python3 - "$1" <<'BASELINE_PY'
from pathlib import Path
import base64, hashlib, os, sys, tempfile
p = Path(sys.argv[1]).resolve()
data = base64.b64decode("")
expected = "4a49af5d4a58ec91c96b263082206adc361c31ebc4993b4c658949728164e66a"
assert hashlib.sha256(data).hexdigest() == expected
if not p.is_file():
    raise SystemExit("TARGET_COPY must be an existing regular file")
mode = p.stat().st_mode & 0o777
fd, name = tempfile.mkstemp(prefix=".rollback-", dir=p.parent)
try:
    with os.fdopen(fd, "wb") as f:
        f.write(data)
    os.chmod(name, mode)
    os.replace(name, p)
finally:
    if os.path.exists(name):
        os.unlink(name)
assert hashlib.sha256(p.read_bytes()).hexdigest() == expected
print("RESTORED sha256=" + expected)
BASELINE_PY
